 "content": "def transform(grid):
    """Color each 3x3 zero-shaped cavity with the matching motif's color."""
    h, w = len(grid), len(grid[0])
    # Motif dictionary from 3x3 monochrome objects in the right-hand panel.
    motifs = {}
    for r0 in range(h):
        for c0 in range(1, w - 2):
            color = grid[r0][c0]
            if color == 0:
                continue
            if r0 + 3 > h or c0 + 3 > w:
                continue
            block = [row[c0:c0 + 3] for row in grid[r0:r0 + 3]]
            colors = {v for row in block for v in row if v != 0}
            if len(colors) != 1:
                continue
            color = next(iter(colors))
            shape = tuple(tuple(1 if v == color else 0 for v in row) for row in block)
            # Only use complete motifs surrounded by zero/background and avoid
            # interpreting fragments by requiring each occupied row/column to be in block.
            if all(any(row) for row in shape) and all(any(shape[r][c] for r in range(3)) for c in range(3)):
                motifs[shape] = color

    out = [row[:5] for row in grid]
    # Panel separators are full-color rows; each panel between separators has
    # three rows and an inner 3x3 cavity at columns 1..3.
    starts = [r for r in range(h - 2) if all(grid[r][c] == grid[r][0] for c in range(5)) and grid[r][0] != 0]
    for r in starts:
        if r + 3 >= h:
            continue
        base = grid[r][0]
        if not all(grid[r][c] == base for c in range(5)):
            continue
        if not all(grid[r + 4][c] == base for c in range(5)) if r + 4 < h else False:
            continue
        cavity = tuple(tuple(1 if grid[rr][cc] == 0 else 0 for cc in range(1, 4)) for rr in range(r + 1, r + 4))
        color = motifs.get(cavity)
        if color is not None:
            for rr in range(r + 1, r + 4):
                for cc in range(1, 4):
                    if grid[rr][cc] == 0:
                        out[rr][cc] = color
    return out
