 "content": "from collections import deque


def _trim(mask):
    rows = [r for r, row in enumerate(mask) if any(row)]
    cols = [c for c in range(len(mask[0])) if any(mask[r][c] for r in range(len(mask)))]
    if not rows or not cols:
        return ()
    return tuple(tuple(mask[r][c] for c in cols) for r in rows)


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame_color = grid[0][0]
    left_w = 0
    while left_w < w and grid[0][left_w] == frame_color:
        left_w += 1

    # Convert each right-panel colored component into its tight binary shape.
    seen = set()
    motifs = {}
    for r in range(h):
        for c in range(left_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and left_w <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            mask = [[int((y, x) in cells) for x in range(c0, c1 + 1)] for y in range(r0, r1 + 1)]
            motifs[_trim(mask)] = color

    out = [row[:left_w] for row in grid]
    separators = [r for r in range(h) if all(grid[r][c] == frame_color for c in range(left_w))]
    for top, bottom in zip(separators, separators[1:]):
        if bottom - top <= 1:
            continue
        zero_mask = [[int(grid[r][c] == 0) for c in range(1, left_w - 1)]
                     for r in range(top + 1, bottom)]
        shape = _trim(zero_mask)
        color = motifs.get(shape)
        if color is not None:
            for r in range(top + 1, bottom):
                for c in range(1, left_w - 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
